import subprocess, sys, os
def run(args, env=None, stdin=None):
    e = dict(os.environ); e.pop('NO_COLOR',None) if env and env.get('_nocolor_unset') else None
    if env:
        for k,v in env.items():
            if k=='_nocolor_unset': continue
            if v is None: e.pop(k,None)
            else: e[k]=v
    p = subprocess.run(['/workspace/executable']+args, capture_output=True, env=e, input=stdin)
    return p
if __name__=='__main__':
    p = run(sys.argv[1:])
    print('EXIT', p.returncode)
    for ln in p.stdout.decode('utf8',errors='replace').split('\n'):
        print(repr(ln), 'len=%d'%len(ln))
    if p.stderr:
        print('STDERR', repr(p.stderr.decode()))
