import subprocess,os
base=dict(os.environ)
def snipline(w,style):
    args=['--color=never','--decorations=always','--terminal-width',str(w),'--style='+style,'-r','1:1','-r','5:5','g.txt']
    p=subprocess.run(['/workspace/executable']+args,capture_output=True,env=base,cwd='/tmp/gr')
    for l in p.stdout.decode(errors='replace').split('\n'):
        if '8<' in l: return l
    return None
def predict(w,pw,grid):
    if pw and w < pw+5: pw=0
    if pw==0: pre=''
    else:
        field=pw-(3 if grid else 1)
        pre=(' ...'+' '*(field-4))+(' │ ' if grid else '')
    n=w-len(pre); L=(n-1)//4; D=(n-2)//2
    return pre+'─ '*L+'8<'+' ─'*(D-L)
